#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, w;
    cin >> n >> w;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int e = 0, o = 0;
    vector<int> cuts;
    for (int i = 0; i < n - 1; i++) {
        if ((a[i] & 1) == 0) e++;
        else o++;
        if (e == o) {
            cuts.push_back(abs(a[i] - a[i + 1]));
        }
    }

    int size = (int)cuts.size();
    vector<vector<int>> dp(size + 1, vector<int>(w + 1, 0));

    for (int i = 1; i <= size; i++) {
        int val = cuts[i - 1];
        for (int j = 1; j <= w; j++) {
            if (val <= j) {
                dp[i][j] = max(1 + dp[i - 1][j - val], dp[i - 1][j]);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    cout << dp[size][w] << "\n";

    return 0;
}
